// Block (composition) — a customer-proof section combining a quote, author, and logos.
// Container caps measure; Stack owns arrangement, Avatar owns identity look, and this Block owns content structure.
import type { ReactNode, Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Container } from "../layouts/Container";
import { Stack } from "../layouts/Stack";
import "./SocialProof.css";

export interface SocialProofProps {
  quote?: ReactNode;
  author?: {
    name: string;
    role?: string;
    avatarSrc?: string;
  };
  logos?: ReactNode[];
  className?: string;
  ref?: Ref<HTMLElement>;
}

function initials(name: string) {
  return name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

export function SocialProof({ quote, author, logos, className, ref }: SocialProofProps) {
  return (
    <Container
      as="section"
      ref={ref}
      span={8}
      padding="none"
      aria-label="Customer proof"
      className={className ? `sd-socialproof ${className}` : "sd-socialproof"}
    >
      <Stack align="center" gap="x-large" className="sd-socialproof__content">
        {(quote || author) && (
          <Stack align="center" gap="medium" className="sd-socialproof__testimonial">
            {quote && (
              <blockquote className="sd-socialproof__quote sd-type-body-medium">
                {quote}
              </blockquote>
            )}
            {author && (
              <Stack direction="row" align="center" gap="small" className="sd-socialproof__author">
                <Avatar src={author.avatarSrc} size="small" alt={author.name}>
                  {initials(author.name)}
                </Avatar>
                <Stack gap="2x-small" className="sd-socialproof__identity">
                  <span className="sd-socialproof__name sd-type-body-medium">{author.name}</span>
                  {author.role && (
                    <span className="sd-socialproof__role sd-type-caption-medium">{author.role}</span>
                  )}
                </Stack>
              </Stack>
            )}
          </Stack>
        )}
        {logos && logos.length > 0 && (
          <Stack
            direction="row"
            align="center"
            justify="center"
            gap="small"
            wrap
            className="sd-socialproof__logos"
          >
            {logos.map((logo, index) => (
              <span key={index} className="sd-socialproof__logo">
                {logo}
              </span>
            ))}
          </Stack>
        )}
      </Stack>
    </Container>
  );
}

.sd-socialproof {
  width: 100%;
  text-align: center;
}

.sd-socialproof__quote,
.sd-socialproof__name,
.sd-socialproof__role {
  margin: 0;
}

.sd-socialproof__role {
  color: var(--sd-color-text-muted);
}

.sd-socialproof__logos {
  width: 100%;
}

.sd-socialproof__logo {
  min-width: 0;
}
